\hat A_t^{GAE} &amp;amp;= \delta_t+\gamma\lambda \hat A_{t+1}^{GAE}\\
&amp;amp; = \delta_t + \sum_{l\geq 0} (\gamma \lambda)^l\hat A_{t+1}^{GAE}
\end{aligned}
