&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#393A34;--shiki-dark:#DBD7CAEE&#34;&gt;                scores&lt;/span&gt;&lt;span style=&#34;color:#2993a3;--shiki-dark:#5eaab5&#34;&gt;[&lt;/span&gt;&lt;span style=&#34;color:#393A34;--shiki-dark:#DBD7CAEE&#34;&gt;i&lt;/span&gt;&lt;span style=&#34;color:#2993a3;--shiki-dark:#5eaab5&#34;&gt;]&lt;/span&gt;&lt;span style=&#34;color:#999999;--shiki-dark:#666666&#34;&gt; =&lt;/span&gt;&lt;span style=&#34;color:#393A34;--shiki-dark:#DBD7CAEE&#34;&gt; scores&lt;/span&gt;&lt;span style=&#34;color:#2993a3;--shiki-dark:#5eaab5&#34;&gt;[&lt;/span&gt;&lt;span style=&#34;color:#393A34;--shiki-dark:#DBD7CAEE&#34;&gt;i&lt;/span&gt;&lt;span style=&#34;color:#2993a3;--shiki-dark:#5eaab5&#34;&gt;]&lt;/span&gt;&lt;span style=&#34;color:#AB5959;--shiki-dark:#CB7676&#34;&gt; -&lt;/span&gt;&lt;span style=&#34;color:#393A34;--shiki-dark:#DBD7CAEE&#34;&gt; id2mean&lt;/span&gt;&lt;span style=&#34;color:#2993a3;--shiki-dark:#5eaab5&#34;&gt;[&lt;/span&gt;&lt;span style=&#34;color:#393A34;--shiki-dark:#DBD7CAEE&#34;&gt;index&lt;/span&gt;&lt;span style=&#34;color:#1e754f;--shiki-dark:#4d9375&#34;&gt;[&lt;/span&gt;&lt;span style=&#34;color:#393A34;--shiki-dark:#DBD7CAEE&#34;&gt;i&lt;/span&gt;&lt;span style=&#34;color:#1e754f;--shiki-dark:#4d9375&#34;&gt;]&lt;/span&gt;&lt;span style=&#34;color:#2993a3;--shiki-dark:#5eaab5&#34;&gt;]&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&lt;code&gt;compute_grpo_vectorized_outcome_advantage&lt;/code&gt; &amp;#x5F52;&amp;#x4E00;&amp;#x5316;&amp;#x7684;&amp;#x5411;&amp;#x91CF;&amp;#x5B9E;&amp;#x73B0;, &amp;#x6BCF;&amp;#x4E00;&amp;#x4E2A;&amp;#x56DE;&amp;#x7B54;&amp;#x57FA;&amp;#x4E8E;&amp;#x5E73;&amp;#x5747;&amp;#x503C;&amp;#x83B7;&amp;#x5F97;&amp;#x6B63;advantage&amp;#x548C;&amp;#x8D1F;advantage&lt;/p&gt;
&lt;p&gt;GRPO &amp;#x5728;&amp;#x4E00;&amp;#x4E2A;&amp;#x95EE;&amp;#x9898;&amp;#x7684;Rollout &amp;#x4E2D;&amp;#x524D;&amp;#x5411;&amp;#x751F;&amp;#x6210;&amp;#x591A;&amp;#x4E2A;&amp;#x7B54;&amp;#x6848;&amp;#x6216;&amp;#x8005;&amp;#x63A8;&amp;#x7406;&amp;#x7ED3;&amp;#x679C;&amp;#xFF0C;&amp;#x518D;&amp;#x8FDB;&amp;#x884C;&amp;#x8BC4;&amp;#x5206;&amp;#xFF0C;&amp;#x5F97;&amp;#x5230;&amp;#x76F8;&amp;#x5BF9;&amp;#x7684;advantage&lt;/p&gt;
&lt;p&gt;&lt;code&gt;compute_grpo_passk_outcome_advantage&lt;/code&gt; passk reward&amp;#xFF0C; &amp;#x53EA;&amp;#x6709;&amp;#x6700;&amp;#x4F18;&amp;#x7684;&amp;#x56DE;&amp;#x7B54;&amp;#x624D;&amp;#x80FD;&amp;#x83B7;&amp;#x5F97; advantage, &amp;#x5F53;&amp;#x7EC4;&amp;#x5185;&amp;#x6709;&amp;#x591A;&amp;#x4E2A;&amp;#x6700;&amp;#x9AD8; advantage &amp;#x65F6;&amp;#xFF0C;&amp;#x8FD9;&amp;#x4E9B;&amp;#x56DE;&amp;#x7B54;&amp;#x90FD;&amp;#x5206;&amp;#x914D; advantage&lt;/p&gt;
&lt;h3 id=&#34;gdpo&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#gdpo&#34;&gt;#&lt;/a&gt; GDPO&lt;/h3&gt;
&lt;p&gt;&lt;code&gt;compute_gdpo_outcome_advantage&lt;/code&gt;[&lt;a class=&#34;citation-link&#34; id=&#34;cite-liu2026gdpogrouprewarddecouplednormalization-1&#34; href=&#34;#ref-liu2026gdpogrouprewarddecouplednormalization&#34; data-cite-key=&#34;liu2026gdpogrouprewarddecouplednormalization&#34; title=&#34;GDPO: Group reward-Decoupled Normalization Policy Optimization for Multi-reward RL Optimization&#34;&gt;2&lt;/a&gt;]&lt;br&gt;
GDPO&amp;#x7684;&lt;/p&gt;
&lt;p&gt;Step1. Rollout&amp;#x7684;&lt;strong&gt;&amp;#x7EC4;&amp;#x5185;&lt;/strong&gt;&amp;#x5F52;&amp;#x4E00;&amp;#x5316;&amp;#x4E3A;advantage&lt;/p&gt;
&lt;p&gt;&lt;span class=&#34;katex-display&#34;&gt;&lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34; display=&#34;block&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;msub&gt;&lt;mi&gt;A&lt;/mi&gt;&lt;mi&gt;k&lt;/mi&gt;&lt;/msub&gt;&lt;mo&gt;&amp;#x2190;&lt;/mo&gt;&lt;mfrac&gt;&lt;mrow&gt;&lt;msub&gt;&lt;mi&gt;r&lt;/mi&gt;&lt;mi&gt;k&lt;/mi&gt;&lt;/msub&gt;&lt;mo&gt;&amp;#x2212;&lt;/mo&gt;&lt;msub&gt;&lt;mover accent=&#34;true&#34;&gt;&lt;mi&gt;r&lt;/mi&gt;&lt;mo&gt;&amp;#x2C9;&lt;/mo&gt;&lt;/mover&gt;&lt;mi&gt;k&lt;/mi&gt;&lt;/msub&gt;&lt;/mrow&gt;&lt;mrow&gt;&lt;mi&gt;&amp;#x3C3;&lt;/mi&gt;&lt;mo&gt;+&lt;/mo&gt;&lt;mi&gt;&amp;#x3B5;&lt;/mi&gt;&lt;/mrow&gt;&lt;/mfrac&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;A_k \gets \frac{r_k - \bar r_k}{\sigma + \varepsilon}
